<h1><?= te('Join our talent pool') ?></h1><p class="sub"><?= te('Apply for future opportunities without choosing a current requisition.') ?></p>
<form class="card" method="post" enctype="multipart/form-data"><?= csrf_field() ?><label><?= te('Full name') ?><input name="name" maxlength="190" required autocomplete="name"></label><label><?= te('Email') ?><input name="email" type="email" required maxlength="190" autocomplete="email"></label><label><?= te('Phone') ?><input name="phone" maxlength="40" autocomplete="tel"></label><label><?= te('Resume · PDF or DOCX, maximum 5 MB') ?><input name="resume" type="file" accept=".pdf,.docx"></label><label><input name="consent" type="checkbox" required style="width:auto"> <?= te('I authorize the hiring agency to review my application and contact me about opportunities.') ?></label><button class="btn"><?= te('Apply') ?></button></form>
